export function resolveCraftTemplateSlug(slugOrId?: string | null): string | null {
  if (!slugOrId) return null;
  const key = slugOrId.toLowerCase().trim();
  if (CRAFT_TEMPLATE_SLUG_MAP[key]) return CRAFT_TEMPLATE_SLUG_MAP[key];
  const withoutCine = key.replace(/^cine-/, '');
  if (CRAFT_TEMPLATE_SLUG_MAP[withoutCine]) return CRAFT_TEMPLATE_SLUG_MAP[withoutCine];
  return null;
}
